export const EY_UNIQUE_PROJECTS = CHANDAK_EY_PROJECTS.map(p => p.name);

export const EY_PROJECT_COLUMNS = CHANDAK_EY_TOWERS.map(t => ({
  project: CHANDAK_EY_PROJECTS.find(p => p.id === t.projectId)?.name || t.projectId,
  tower: t.towerName
}));

export const EY_TENDER_PACKAGES = CHANDAK_EY_PACKAGES.map(pkg => ({
  id: pkg.id,
  discipline: pkg.disciplineName,
  subPackage: pkg.subPackageName,
  consultant: pkg.defaultConsultant || "",
  statuses: Object.fromEntries(
    CHANDAK_EY_TOWERS.map(t => {
      const p = CHANDAK_EY_PROJECTS.find(pr => pr.id === t.projectId);
      const key = `${t.projectId}__${t.id}__${pkg.id}`;
      const statusEntry = CHANDAK_EY_MATRIX_ENTRIES[key];
      return [`${p?.name || t.projectId}__${t.towerName}`, statusEntry ? statusEntry.currentStage : "NA"];
    })
  )
}));

export const EY_LOOK_AHEAD_ITEMS = CHANDAK_EY_LOOK_AHEADS;

export const EY_LIAISON_CONSULTANTS = CHANDAK_EY_AUTHORITIES.map(a => a.authorityName);

